const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function withRetry(fn, { attempts = 5, base = 100, cap = 2000, isRetryable = () => true } = {}) {
  for (let n = 0; ; n++) {
    try {
      return await fn();
    } catch (err) {
      if (n === attempts - 1 || !isRetryable(err)) throw err;
      const ceiling = Math.min(cap, base * 2 ** n);
      await sleep(Math.random() * ceiling);
    }
  }
}
